#!/usr/bin/env python3
"""Simple Lisp interpreter in Python."""

import ast
import sys
from typing import Any, List, Union

# Supported operations
ARITHMETIC = {
    '+': lambda x, y: x + y,
    '-': lambda x, y: x - y,
    '*': lambda x, y: x * y,
    '/': lambda x, y: x / y if y != 0 else ZeroDivisionError("division by zero"),
}

LOGICAL = {
    'and': lambda a, b: bool(a) and bool(b),
    'or': lambda a, b: bool(a) or bool(b),
    'not': lambda a: not bool(a),
}

def evaluate(expr: Any) -> Any:
    """Evaluate a Lisp expression."""
    if isinstance(expr, list):
        # S-expression: apply the first element as function to the rest
        func = expr[0]
        args = expr[1:] if len(expr) > 1 else []
        return evaluate(func)(*args)
    elif isinstance(expr, (int, float)):
        return expr
    elif isinstance(expr, str):
        # Atom - could be a symbol or number as string
        try:
            return int(expr)
        except ValueError:
            pass
        try:
            return float(expr)
        except ValueError:
            pass
        # If it looks like a boolean string
        if expr.lower() in ('true', 'false'):
            return expr.lower() == 'true'
    elif isinstance(expr, bool):
        return expr
    else:
        raise TypeError(f"Unsupported expression type: {type(expr)}")

def print_value(value: Any) -> None:
    """Print a value in Lisp style."""
    if isinstance(value, list):
        # Print as ( ... )
        items = [print_value(item) for item in value]
        return "(" + " ".join(items) + ")"
    elif isinstance(value, bool):
        return str(value).upper()
    elif isinstance(value, int):
        return str(value)
    elif isinstance(value, float):
        # Format floats nicely
        if value == int(value):
            return str(int(value))
        else:
            return f"{value}"
    else:
        return repr(value)

def run_program(program: List[Any]) -> Any:
    """Run a Lisp program and return the result."""
    # First, evaluate the entire program (which is an expression)
    result = evaluate(program)
    print_value(result)
    return result

if __name__ == "__main__":
    # Read from stdin or use hardcoded examples
    if len(sys.argv) > 1:
        # Read from file
        with open(sys.argv[1], 'r') as f:
            program = f.read().strip()
    else:
        # Interactive mode - read S-expressions one per line
        print("Lisp Interpreter (type expressions, Ctrl-D to finish):")
        program = []
        while True:
            try:
                line = input(">>> ").strip()
                if not line:
                    continue
                # Parse S-expression
                program.append(eval(line))
            except EOFError:
                break
    run_program(program)

